        cx, cy = (w - 1) / 2.0, (h - 1) / 2.0
        dist_center = abs(x - cx) + abs(y - cy)
        base -= 0.5 * dist_center

        # Mild attraction to opponent position to enable flipping when possible.
        base -= 0.1 * (abs(x - ox) + abs(y - oy))

        return base

    # Candidate set: immediate reachable cells; if none helpful, use stay.
    best_move = [0, 0]
    best_val = -10**18

